import {
    Acl,
    Role,
    default_view,
    ApplicationMenu,
    Property,
    UserPreference,
    CrossScopePrivilege,
    List,
    Record,
    Table,
    BusinessRule,
    ClientScript,
    StringColumn,
    BooleanColumn,
} from '@servicenow/sdk/core'

const role = Role({
    name: 'x_meta.role',
})

Acl({
    $id: Now.ID['acl-id'],
    operation: 'write',
    type: 'record',
    table: 'task',
    roles: [role],
    condition: 'priority=2^active=true',
    field: 'description',
    appliesTo: 'active=true',
})

List({
    table: 'cmdb_ci_server',
    view: default_view,
    columns: ['name', 'business_unit', 'vendor', 'cpu_type'],
})

const appCategory = Record({
    table: 'sys_app_category',
    $id: Now.ID[`sys_app_category_my_app`],
    data: {
        name: 'My App Category',
        style: 'border: 1px solid #96bcdc; background-color: #FBFBFB;',
        default_order: 100,
    },
})

ApplicationMenu({
    $id: Now.ID['My App Menu'],
    title: 'My App Menu',
    hint: 'This is a hint',
    description: 'This is a description',
    category: appCategory,
    roles: [role],
    active: true,
})

UserPreference({
    name: 'email',
    $id: Now.ID['admin_email'],
    type: 'string',
    value: 'admin@example.com',
})

CrossScopePrivilege({
    $id: Now.ID['cross_1'],
    targetName: 'Script Type',
    targetScope: 'sn_example',
    status: 'allowed',
    targetType: 'scriptable',
    operation: 'execute',
})

BusinessRule({
    name: 'ts',
    table: 'blah',
    $id: '1',
    script: ``,
    when: 'after',
})

ClientScript({
    $id: Now.ID['40d145bffd224a09f6c60a7676d985e6'],
    type: 'onLoad',
    table: 'incident',
    script: `function onLoad(){ console.log("execute this code") }`,
    name: 'handle_incidents',
    description: 'cool',
    uiType: 'all',
})

export const x_meta_demo = Table({
    name: 'x_meta_demo',
    schema: {
        name: StringColumn({ mandatory: true, maxLength: 255 }),
        active: BooleanColumn({ default: true }),
        description: StringColumn({ maxLength: 4000 }),
    },
})

Property({
    $id: Now.ID['newProp'],
    name: 'x_meta.some.new.prop',
    type: 'string',
    value: 'hello',
    description: 'Brand new prop',
    roles: {
        read: ['admin'],
    },
})
